entries[414564] = { ["name"] = "Cursed Cloth", ["text"] = "3.5 sec cast\nReagents:\nWartorn Scrap (50), Felcloth (20), Essence of Undeath (6), Dark Rune (2), Frozen Rune\nThis cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nDiscovery:\nNaxxramas\n\nCursed Cloth\nBinds when picked up\nUse: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\nThe resulting item will become Warbound and the desecration can be purified by a Mage, Priest, or Warlock who is willing to acquire the necessary reagents." }
entries[414565] = { ["name"] = "Languished Leather", ["text"] = "3.5 sec cast\nReagents:\nWartorn Scrap (50), Enchanted Leather (40), Essence of Undeath (6), Dark Rune (2), Frozen Rune\nThis cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nDiscovery:\nNaxxramas\n\nLanguished Leather\nBinds when picked up\nUse: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\nThe resulting item will become Warbound and the desecration can be purified by a Druid or Rogue who is willing to acquire the necessary reagents." }
entries[414566] = { ["name"] = "Scourged Scales", ["text"] = "3.5 sec cast\nReagents:\nWartorn Scrap (50), Enchanted Leather (40), Essence of Undeath (6), Dark Rune (2), Frozen Rune\nThis cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nDiscovery:\nNaxxramas\n\nScourged Scales\nBinds when picked up\nUse: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\nThe resulting item will become Warbound and the desecration can be purified by a Hunter or Shaman who is willing to acquire the necessary reagents." }
entries[414567] = { ["name"] = "Undeath Metal", ["text"] = "3.5 sec cast\nReagents:\nWartorn Scrap (50), Arcanite Bar (10), Essence of Undeath (6), Dark Rune (2), Frozen Rune\nThis cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nDiscovery:\nNaxxramas\n\nUndeath Metal\nBinds when picked up\nUse: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\nThe resulting item will become Warbound and the desecration can be purified by a Paladin or Warrior who is willing to acquire the necessary reagents." }
